) AS (
  VALUES 
    (168::BIGINT, 'A mi me gustó mucho las clases, me encantó que nos dejara ser creativos y hacer obras, y en general las calificaciones son lindos, la recomiendo 100%.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'f71a176e8dcf3d94725facaa5a2b2b1d683eb25242ec05f457f71bc8f1188992'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'El curso en sí la verdad me pareció un poco aburrido, pero nada mal. Las primeras semanas son actividades para conocerse e individuales, luego un par de semanas teóricas y el resto es casi cada 15 días presentaciones teatrales en grupo(mucho cringe). Hay mejores culturales , pero ella es un amor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2025-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'cbd099ecf2278371771a8f531ee3e3aff98facac9470d72bb2e322edff3c780c'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'Me hubiera encantado quedarme en esa clase para volverla a llevar con Andrea'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-24T00:00:00+00:00'::TIMESTAMPTZ, '7cf874844ce38949c51adef0b488c12a6b0dc3ef0b0b59a68cc2133e7e5bd705'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'Ojalá hagan artes dramáticas II, es un curso muy entretenido e interesante en el que uno aprende a soltarse y desenvolverse mejor. La profe es muy agradable y muy linda persona, crea dinámicas muy disfrutables y hace que el curso sea super bonito'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-14T00:00:00+00:00'::TIMESTAMPTZ, '420aed3f0e48346649accfaf9dbb46618b59a6cbd6f58223ce28790f5778700c'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'Una excelente profesora, super recomendado matricular con ella. Es una cultural fácil, sencilla, amena y la profe crea un espacio super seguro para que nadie se sienta juzgado. Se disfruta mucho la clase y ayuda a romper la rutina de la semana.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-02T00:00:00+00:00'::TIMESTAMPTZ, '82b1c1a3203cf1314d62e20ccbdd8bb91697e8ae9bc018c4bfb7e568af6d7479'::TEXT, ARRAY[497]::BIGINT[]),
    (168::BIGINT, 'La mejor clase del semestre. Es muy interesante y es un tiempo para desestresarse. La profe es un rayito de sol y la recomiendo 100%. El ambiente en clase es demasiando lindo y seguro. Disfrute su clase muchisimo!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-11-17T00:00:00+00:00'::TIMESTAMPTZ, '4257921e10fac2b623433e60c57ccb9ae0aca40b65d2907d60728a168ced2101'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'El curso es una bella experiencia. La profe es simpática y crea un ambiente unido y seguro en el aula. Las clases son muy dinámicas. De verdad se vuelve un escape muy lindo de las demás materias.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-07-25T00:00:00+00:00'::TIMESTAMPTZ, '5c092675ad9bb118119e54150e2de8b3cd73393fbde96cefa4d5dccbdaca6d62'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'La profe es súper, una calidad de persona. Intenta escuchar a todos en clase y hacer un espacio seguro, la recomiendo demasiado. Definitivamente matricularía de nuevo con la profe Andrea.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '5ee414a87ed844d01828b1098f7635bd9fb022d73f44e4ad1351af046cde29f7'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'La verdad es una exelente profesora que hace esta clase un espacio seguro y divertido bajo de tanto estrés académico. Meta con ella, creame que se sentirá seguro e incluido. Además, es muy justa y todos participan x igual.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-14T00:00:00+00:00'::TIMESTAMPTZ, '972b9f644106eb22df0d874b14691c07f6ffe97f983ab1022d92f39cf08f7f2c'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'La profe es muy genial, las actividades son muy lindas y entretenidas, con ella uno se siente en un lugar seguro. En general, las evaluaciones son muy sencillas. Es una súper opción para una cultural por qué es fácil y muy disfrutable.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2024-05-31T00:00:00+00:00'::TIMESTAMPTZ, '8d00fb10bd6aa7ed9369a29b15be7034eac2c0536d2b26700332c20c8c76a8b0'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'siempre va a desear que llegue el día de la clase. es un espacio inclusivo y seguro para todes. la profesora hace un trabajo excepcional. las tareas se disfrutan y da una retroalimentación increíble. desde ya estoy manifestando que abran Artes Dramáticas II. :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-08T00:00:00+00:00'::TIMESTAMPTZ, '11ad06997ab4506169dfd14349883f5e7fb33200f8183509664b73063252632a'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'De las mejores clases que he llevado, un espacio para despejarse de todo y reírse un rato. La profe es una persona súper especial con una gran sensibilidad, logra hacer a cada estudiante sentirse valorado. Definitivamente recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes']::TEXT[], '2023-12-06T00:00:00+00:00'::TIMESTAMPTZ, '2d0a198752ea2e6e16985e45773172a26aca492963b3b69d7971226181ce43e6'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'Sus clases son muy divertidas, muy relajantes y muy interesantes. Incluso si no sabes actuar no importa, como ella dice no es una clase de actuación. Es un espacio seguro y muy divertido. Si hubiese Artes Dramáticas II, júrelo que lo matricularía.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'b1d647d09fdfd0074a7b88c904c8b1387cab8399761135051ebcae573fa71552'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'La profe es super buena gente y hace que la clase sea un espacio divertido e inclusivo para todos. Los trabajos son sencillos y casi no quitan tiempo, la verdad recomiendo llevar este curso con ella a cualquier persona, incluso si actuar no es lo tuyo como fue mi caso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-19T00:00:00+00:00'::TIMESTAMPTZ, '35b89fd4b8354eeafd67f9ad535d4196427ff7cf5fd8625e224d75dc72b72d73'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'Hace que las clases se sientan como un espacio para relajarse y vacilar, crea un espacio seguro para todas las personas. Si hubiera Artes Dramáticas 2 sin duda la llevaría con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-12-22T00:00:00+00:00'::TIMESTAMPTZ, 'd134f2380c344014ed5645c51e4b824095b23c37dfb4823747ae94b2898f3d18'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'Es una profe demasiado agradable y linda, utiliza la clase como un espacio para relajarse y olvidarse un poco del caos del semestre, las actividades son muy entretenidas. Incluso siendo un curso virtual uno se entretiene bastante. Es flexible con las entregas de trabajos. La recomiendo 500%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Inspirador']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, '35635b18f434b3bdf652ed53e9df6412c597d61932e5c299f081115c2786b2ca'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'El curso perdió su escencia al ser virtual pero la profe trató de darnos una muy buena clase y lo logró, muy buena persona y trata de que la clase sea como un lugar para despejarse del estrés del semestre'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-08T00:00:00+00:00'::TIMESTAMPTZ, '0757ae3b7dde4f7234ee78722d46902bfc2dbf32bd2175bb64aedbfdd8d4a98d'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'Ella es super linda como persona y como profesora, hace que la clase sea super entretenida, en mi opinión, el semestre que lleve con ella estaba super cargado de cursos y todo, y el día que tenía clases de artes dramáticas, era como un desastres increible, te ríes mucho y disfrutas mucho la clase!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-04-06T00:00:00+00:00'::TIMESTAMPTZ, 'cd29e564f0f2f9f733e819fec8c49de0f79be996727b04a46aa881fde01551b4'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'La mejor profe del mundo. TODAS las personas deberían de matricular con ella, ya sea virtual o PRESENCIAL.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2021-12-20T00:00:00+00:00'::TIMESTAMPTZ, '32b6f7ef7c4dec6a46f35bfa578d157ffeacd289ea648c53105b70408fe1a42f'::TEXT, ARRAY[500]::BIGINT[]),
    (168::BIGINT, 'Es una belleza, la clase es muy interactiva y se disfruta mucho. Las tareas son prácticamente nulas y ella es muy amable. Además en las clases virtuales sale su gatita también 100/10 :D'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, '7edadb560247901019550df547dba991b35379b514bf9954dd74ae021ceb9397'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'La mejor profe!! Hace que te olvides del estrés del semestre. Carismática, alegre, amable... 10/10'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-05-05T00:00:00+00:00'::TIMESTAMPTZ, '6dbf055f8c9f26206f2b1b609d65a11e8887be0dd664cd93192826f905f50bbf'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'Por mi parte, todo perfecto con esta profe, lástima que con la virtualidad se perdió mucho de lo que podía dejar este curso, sin embargo, la profe buscó formas de trabajar incluso en la distancia. Me encantó el curso y la actitud de la profe, nada más que decir.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'c978be94159be1e041ebc0c58ebd04535dcdff743aa75b85044c8ff0f2d3f103'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'Deja trabajos que quitan mucho tiempo: hacer vídeos actuando, editarlos, etc...'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, '8fcd6cefeb76c75bc23ef616a5a97d83d53a046f7f353e8c0a9fd22746b56efd'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'Es una clase de lo mas relajada para olvidarse un rato del semestre.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2019-12-14T00:00:00+00:00'::TIMESTAMPTZ, '693ed251dc0928603f9b2116ced86d5909d96254bf265a9185c59bbc230bce4b'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'Una profesora muy amigable y energética. Hace la clase muy divertida y comunica su visión sobre el teatro de una manera muy comprensible. La clase sirve para dejar el estrés de lado y simplemente disfrutar. Dos reportes de obras sencillos y una puesta en escena final muy buena. 100% recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Clases excelentes']::TEXT[], '2019-11-12T00:00:00+00:00'::TIMESTAMPTZ, '34e8ec7041c63776873b34373af206292434463970a3ec2359f70aabb9347215'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'Una super profe!!! Full recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'bdf41922bdb7914fe5f5941764275b548e87ec16c6f08bac464c97eb1f7a8552'::TEXT, ARRAY[692]::BIGINT[]),
    (168::BIGINT, 'Excelente profe! El curso en sí, requiere 2 informes escritos de obras asistidas fuera de clase y una presentación a final de semestre como de 15 min y eso es lo único tedioso. Sin embargo, es una excelente persona que se esfuerza por brindar un espacio cómodo y libre, todas las semanas se disfruta'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'bcec119be1e6991cefa01670d158a29fc89e47b3b659b181d0b7aecc6391662a'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-07-28T00:00:00+00:00'::TIMESTAMPTZ, '5661c3f0e1299125fb177bc76339de31b5c5f5c48ea9305301b75116a16206c7'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-07-05T00:00:00+00:00'::TIMESTAMPTZ, '7e0b02224cc35b128b0302607da946b06c7ff3afe2ef7b9d09d3f6552ad96a24'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2018-06-24T00:00:00+00:00'::TIMESTAMPTZ, '537bd0da3626267c5108d583ef3a23ee71ce5be0c562c6dc485282af48dc6a88'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'Muy buena profe, recomendada!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'a119f74413f6899508865bdef24b470dfd7648aab0b858d376c53f9663113246'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'Excelente profe, en la clase uno se desastrosa demasiado y hasta en un momento termina llorando jaja, muy recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2017-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'b0d5433993c5e50f9875bff2b1582ef2d7bb631e323f73fb4778752b4e390330'::TEXT, ARRAY[498]::BIGINT[]),
    (168::BIGINT, 'Meter teatro con la profe Andrea es de las mejores decisiones. Son dos horas a la semana donde se encarga de que se te olvide lo que es estar en el TEC. Las clases son super participativas, entretenidas y se aprende bastante en el poco tiempo que se tiene. Es LA profesora!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-08T00:00:00+00:00'::TIMESTAMPTZ, '20d9094e948a21093d8eeb1c9807a468c030720289be9d0cade376942a178a7e'::TEXT, ARRAY[498]::BIGINT[]),
